#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <set>
#include <utility>
using namespace std;

int main(){
vector<double> x={1,2,3},y={2,3,7};
double xx=0,xy=0,residualDot=0;
for(int i=0;i<3;i++){xx+=x[i]*x[i];xy+=x[i]*y[i];}
double beta=xy/xx;
for(int i=0;i<3;i++)residualDot+=x[i]*(y[i]-beta*x[i]);
cout<<beta<<" "<<residualDot<<endl;
if(fabs(residualDot)>1e-10)return 1;
    return 0;
}

