#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <set>
#include <utility>
using namespace std;

int main(){
vector<double> x={1,2,3,4},y={2,4,6,8};
double weight=0,learningRate=0.01;
for(int epoch=0;epoch<200;epoch++){
    double gradient=0;
    for(int i=0;i<4;i++)
        gradient+=2*(weight*x[i]-y[i])*x[i]/4;
    weight-=learningRate*gradient;
}
cout<<"Fitted slope "<<weight<<endl;
    return 0;
}

