#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <set>
#include <utility>
using namespace std;

int main(){
vector<double> x={1,2,3,4,5,6},y={1,1.2,1.1,4,4.5,4.8};
double best=1e100,threshold=0;
for(double cutoff:{1.5,2.5,3.5,4.5,5.5}){
    double left=0,right=0;int nl=0,nr=0;
    for(int i=0;i<6;i++){
        if(x[i]<cutoff){left+=y[i];nl++;}
        else{right+=y[i];nr++;}
    }
    left/=nl;right/=nr;
    double loss=0;
    for(int i=0;i<6;i++)loss+=pow(y[i]-(x[i]<cutoff?left:right),2);
    if(loss<best){best=loss;threshold=cutoff;}
}
cout<<threshold<<" "<<best<<endl;
    return 0;
}

